const ctx = $('Input').first().json;
const userContent = 'Client: ' + ctx.client_name +
'\n--- P&L (current 12mo + prior 12mo) ---\n' + JSON.stringify({ last12: ctx.financials?.pnl_last_12mo, prior12: ctx.financials?.pnl_prior_12mo }) +
'\n--- BALANCE SHEET ---\n' + JSON.stringify(ctx.financials?.balance_sheet ?? {}) +
'\n--- PAYROLL ---\n' + JSON.stringify(ctx.payroll ?? {});
const payload = {
  model: 'claude-opus-4-8',
  max_tokens: 8000,
  system: "You are building a 4-metric client scorecard and a short financial review for a quarterly meeting. Compute revenue (last 12 mo vs prior 12 mo), gross and net profit margin, and owner take-home (salary + distributions + benefits) for both periods. Then write a brief narrative that explains WHAT DRIVES the changes. Frame the story around tax and owner outcomes, not CFO-level detail. Flag any figure that looks like an accounting artifact rather than real performance. Output only the JSON schema.",
  messages: [{ role: 'user', content: userContent }],
  output_config: { effort: 'high', format: { type: 'json_schema', schema: {"type": "object", "additionalProperties": false, "required": ["revenue", "gross_margin", "net_margin", "owner_take_home", "narrative", "artifacts"], "properties": {"revenue": {"type": "object", "additionalProperties": false, "required": ["current", "prior", "pct_change"], "properties": {"current": {"type": "number"}, "prior": {"type": "number"}, "pct_change": {"type": "number"}}}, "gross_margin": {"type": "object", "additionalProperties": false, "required": ["current", "prior"], "properties": {"current": {"type": "number"}, "prior": {"type": "number"}}}, "net_margin": {"type": "object", "additionalProperties": false, "required": ["current", "prior"], "properties": {"current": {"type": "number"}, "prior": {"type": "number"}}}, "owner_take_home": {"type": "object", "additionalProperties": false, "required": ["current", "prior"], "properties": {"current": {"type": "number"}, "prior": {"type": "number"}}}, "narrative": {"type": "string"}, "artifacts": {"type": "array", "items": {"type": "string"}}}} } }
};
return [{ json: { ...$json, payload } }];

// Structured outputs: the JSON arrives as a string in content[0].text.
const text = $json.content?.[0]?.text ?? '{}';
let out; try { out = JSON.parse(text); } catch (e) { out = { parse_error: true, raw: text }; }
const ctx = $('Input').first().json;
return [{ json: { ...ctx, scorecard: out } }];
